<?php require_once "../config/database.php";require_once "../includes/functions.php";require_admin();$rows=$pdo->query("SELECT * FROM products ORDER BY id DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Products Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><?php include "../includes/navbar.php";?><main class="container page"><span class="eyebrow">ADMIN</span><h1>Products.</h1><div class="table-wrap"><table><tr><th>ID</th><th>Name</th><th>Brand</th><th>Price</th><th>Stock</th></tr><?php foreach($rows as $r):?><tr><td><?=$r["id"]?></td><td><?=e($r["name"])?></td><td><?=e($r["brand"])?></td><td>Rs. <?=number_format($r["price"],2)?></td><td><?=$r["stock"]?></td></tr><?php endforeach;?></table></div></main></body></html>